package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public class IndexedMaterialTest {public static void main(String[] args)throws Exception{int accepted=0,rejected=0,texels=0;
 try(DirectoryStream<Path> files=Files.newDirectoryStream(Paths.get(args[0]),"*.nsp")){for(Path file:files){if(file.getFileName().toString().startsWith("bad-"))continue;NativeScenePacket packet=new NativeScenePacket(1,Files.readAllBytes(file));NativeWorldScene world=new NativeWorldScene(packet);boolean allowed=true;for(int i=0;i<world.surfaceCount();i++){NativeWorldScene.Surface s=world.surface(i);allowed&=(s.lit?((s.mode==3||s.mode==8)&&s.corners==4):(s.mode==0||s.mode==1||s.mode==2||s.mode==4||s.mode==5||s.mode==6||s.mode==7));}
 for(int si=0;si<world.surfaceCount();si++){NativeWorldScene.Surface surface=world.surface(si);if(surface.lit||(surface.mode!=1&&surface.mode!=2&&surface.mode!=4&&surface.mode!=5&&surface.mode!=6&&surface.mode!=7))continue;ByteBuffer indices=surface.originalIndices(),states=surface.states(),image=NativeSceneDrawPlan.uploadImage(surface.texture(),indices,states);for(int pixel=0;pixel<surface.width*surface.height;pixel++){if(indices!=null){if(image.get(pixel*4)!=indices.get(pixel))throw new AssertionError("Direct index changed");texels++;}if(states!=null&&((image.get(pixel*4+3)&255)==0)!=(states.get(pixel)==0))throw new AssertionError("Direct state changed");}}
 try{NativeSceneDrawPlan plan=new NativeSceneDrawPlan(packet);if(!allowed)throw new AssertionError("Unsupported material accepted");accepted++;for(int i=0;i<plan.count();i++){NativeSceneDrawPlan.Draw draw=plan.draw(i);if(draw.model)continue;NativeWorldScene.Surface surface=world.surface(draw.index);if(surface.lit){int pixels=surface.width*surface.height;ByteBuffer sourceIndices=surface.originalIndices(),sourceStates=surface.states(),sourceLight=surface.lighting();if(draw.lighting==null||draw.indexed!=(sourceIndices!=null))throw new AssertionError("Lit indexed flag");for(int level=0;level<16;level++){ByteBuffer variant=draw.lighting.variant(level);if(!variant.isDirect()||!variant.isReadOnly()||variant.remaining()!=pixels*4)throw new AssertionError("Lit upload ownership");for(int pixel=0;pixel<pixels;pixel++){int state=sourceStates.get((level+1)*pixels+pixel)&255,alpha=state==0?0:state==1?128:255;if((variant.get(pixel*4+3)&255)!=alpha)throw new AssertionError("Lit write state");if(sourceIndices!=null){if(variant.get(pixel*4)!=sourceIndices.get((level+1)*pixels+pixel))throw new AssertionError("Lit mapped index changed");texels++;}else for(int channel=0;channel<3;channel++)if(variant.get(pixel*4+channel)!=sourceLight.get(20+(level*pixels+pixel)*4+channel))throw new AssertionError("Lit RGB changed");}}continue;}ByteBuffer indices=surface.originalIndices(),states=surface.states(),image=draw.image();if(draw.indexed!=(indices!=null)||!image.isDirect()||!image.isReadOnly())throw new AssertionError("Upload ownership");for(int pixel=0;pixel<draw.width*draw.height;pixel++){if(indices!=null){if(image.get(pixel*4)!=indices.get(pixel))throw new AssertionError("Index changed");texels++;}if(states!=null&&((image.get(pixel*4+3)&255)==0)!=(states.get(pixel)==0))throw new AssertionError("Wall state changed");}}
 }catch(IllegalArgumentException e){if(allowed)throw e;rejected++;}}}
 NativeSceneSnapshot scene=new NativeSceneSnapshot(Files.readAllBytes(Paths.get(args[1])));ByteBuffer palette=NativeHistoricalPalette.rgba(scene);int checks=0;for(int y=0;y<160;y++){ByteBuffer row=scene.row(y);for(int i=0;i<256;i++){int color=row.getShort(128+24*4096+i*2)&65535;for(int c=0;c<3;c++){int v=(color>>(c*5))&31;if((palette.get((y*256+i)*4+c)&255)!=((v<<3)|(v>>2)))throw new AssertionError("Historical palette");checks++;}if((palette.get((y*256+i)*4+3)&255)!=255)throw new AssertionError();}}
 if(accepted==0||rejected==0||texels==0)throw new AssertionError();System.out.println("PASS_INDEXED_MATERIAL accepted="+accepted+" rejected="+rejected+" preserved_indices="+texels+" palette_channels="+checks);
 }}